--rcm_offer_sanluongmua_cate_6months

WITH tmp AS (
    SELECT 
        sl.count_bills,
        sl.customer_id,
        sl.categoryid,
        km.score
    FROM pinot."default".rcm_offer_sanluongmua_cate_6months sl
    LEFT JOIN pinot."default".rcm_customerprofile_promotion_metrics km 
        ON sl.customer_id = km.customer_id 
        AND sl.categoryid = km.categoryid 
    WHERE sl.categoryid IN ('7462')
),
tmp_2 AS (
    SELECT 
        customer_id, 
        categoryid, 
        AVG(count_bills) AS count_bills, 
        SUM(score) AS s_score
    FROM tmp
    GROUP BY customer_id, categoryid
)
SELECT tmp_2.customer_id, coalesce( app.co_caidatapp, '0') co_caidatapp
FROM tmp_2 
LEFT JOIN pinot."default".rcm_khachhang_coappbhx app 
    ON tmp_2.customer_id = app.customer_id
ORDER BY count_bills DESC, s_score desc
;

with
customer_orders AS (
    SELECT 
        a.crmcustomerid AS customer_id,
        DATE_TRUNC('month', FROM_UNIXTIME(a.outputdate / 1000 - 25200)) AS order_month
    FROM "pinot-group01"."default".bhx_inventory_inv_outputvoucher a
    JOIN "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b 
        ON a.outputvoucherid = b.outputvoucherid
    JOIN
        "pinot-group01"."default".bhx_bhx_masterdata_pm_product p 
        ON CAST(b.productid  AS VARCHAR) = CAST(p.productid AS VARCHAR)
    WHERE FROM_UNIXTIME(a.outputdate / 1000 - 25200) >= DATE('2025-04-01')
      AND FROM_UNIXTIME(a.outputdate / 1000 - 25200) < DATE('2025-07-01')
      AND b.outputtypeid IN (3, 1903)
      AND a.crmcustomerid > 5
      and p.subgroupid not in (3039, 3059, 3041)
),
customers_with_orders_in_all_3_months AS (
    SELECT distinct customer_id
    FROM customer_orders
    GROUP BY customer_id
    HAVING COUNT(DISTINCT order_month) = 3
)
SELECT COUNT(*) AS num_customers
FROM customers_with_orders_in_all_3_months;




