--- Lấy dskh có mua ở tuần này chưa mua ở tuần khác
 
 with
customer_2 AS (
	SELECT 
	    a.crmcustomerid AS customer_id
	FROM "pinot-group01"."default".bhx_inventory_inv_outputvoucher a
	JOIN "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b 
	    ON a.outputvoucherid = b.outputvoucherid
	JOIN
	    "pinot-group01"."default".bhx_bhx_masterdata_pm_product p 
	    ON CAST(b.productid  AS VARCHAR) = CAST(p.productid AS VARCHAR)
	WHERE 
	  FROM_UNIXTIME(a.outputdate / 1000 - 25200) >= DATE('2025-07-14')
	  AND FROM_UNIXTIME(a.outputdate / 1000 - 25200) < DATE('2025-07-21')
	  AND b.outputtypeid IN ( 1903)
	  AND a.crmcustomerid > 5
	  and p.maingroupid in (1236)
),
customer_3 as (
 SELECT 
    a.crmcustomerid AS customer_id
FROM "pinot-group01"."default".bhx_inventory_inv_outputvoucher a
JOIN "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b 
    ON a.outputvoucherid = b.outputvoucherid
JOIN
    "pinot-group01"."default".bhx_bhx_masterdata_pm_product p 
    ON CAST(b.productid  AS VARCHAR) = CAST(p.productid AS VARCHAR)
WHERE 
  FROM_UNIXTIME(a.outputdate / 1000 - 25200) >= DATE('2025-07-21')
  AND FROM_UNIXTIME(a.outputdate / 1000 - 25200) <= DATE('2025-07-25')
  AND b.outputtypeid IN ( 1903)
  AND a.crmcustomerid > 5
  and p.maingroupid in (1236)
)
SELECT A.customer_id
FROM customer_2 A
LEFT JOIN customer_3 B
ON A.customer_id = B.customer_id
WHERE B.customer_id IS NULL
;

--- 
-- Khách có mua các nhóm hàng VSNC ( Nước rửa chén, Bột Giặt, Nước Giặt, Nước lau nhà) từ tháng 1/2025 - 4/2025 , nhưng  từ tháng 5/2025 đến hiện tại ko có mua nữa.
---
with
customer_2 AS (
	SELECT 
	    a.crmcustomerid AS customer_id
	FROM "pinot-group01"."default".bhx_inventory_inv_outputvoucher a
	JOIN "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b 
	    ON a.outputvoucherid = b.outputvoucherid
	JOIN
	    "pinot-group01"."default".bhx_bhx_masterdata_pm_product p 
	    ON CAST(b.productid  AS VARCHAR) = CAST(p.productid AS VARCHAR)
	WHERE 
	  FROM_UNIXTIME(a.outputdate / 1000 - 25200) >= DATE('2025-01-01')
	  AND FROM_UNIXTIME(a.outputdate / 1000 - 25200) < DATE('2025-05-01')
	  AND b.outputtypeid IN ( 1903, 3)
	  AND a.crmcustomerid > 5
	  and p.subgroupid in (3039, 3059, 3041, 3116)
),
customer_3 as (
 SELECT 
    a.crmcustomerid AS customer_id
FROM "pinot-group01"."default".bhx_inventory_inv_outputvoucher a
JOIN "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b 
    ON a.outputvoucherid = b.outputvoucherid
JOIN
    "pinot-group01"."default".bhx_bhx_masterdata_pm_product p 
    ON CAST(b.productid  AS VARCHAR) = CAST(p.productid AS VARCHAR)
WHERE 
  FROM_UNIXTIME(a.outputdate / 1000 - 25200) >= DATE('2025-05-01')
--  AND FROM_UNIXTIME(a.outputdate / 1000 - 25200) <= DATE('2025-07-25')
  AND b.outputtypeid IN ( 1903,3)
  AND a.crmcustomerid > 5
  and p.subgroupid in (3039, 3059, 3041, 3116)
)
select distinct A.customer_id   --- có trong A không có trong B (anti join)
FROM customer_2 A
LEFT JOIN customer_3 B
ON A.customer_id = B.customer_id
WHERE B.customer_id IS null

