 -- KHách hàng mua hàng có brandid = 7334 từ ngày 14/6 tới ngày 14/8:
 with tmp2 as (
 SELECT 
    distinct a.crmcustomerid AS customer_id,
    CASE WHEN b.outputtypeid = 1903 THEN 1 ELSE 0 END AS is_online
FROM "pinot-group01"."default".bhx_inventory_inv_outputvoucher a
JOIN "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b 
    ON a.outputvoucherid = b.outputvoucherid
JOIN
    "pinot-group01"."default".bhx_bhx_masterdata_pm_product p 
    ON CAST(b.productid  AS VARCHAR) = CAST(p.productid AS VARCHAR)
WHERE 
--  FROM_UNIXTIME(a.outputdate / 1000 - 25200) >= DATE('2025-06-14')
--  AND FROM_UNIXTIME(a.outputdate / 1000 - 25200) <= DATE('2025-08-14')
  b.outputtypeid IN (1903, 3)
  AND a.crmcustomerid > 5 -- lọc KH định danh
  and p.subgroupid in (2980, 3926, 3139, 3141, 3919, 3137, 3138, 3944, 3140, 3945, 3084, 3024, 3083, 3821, 3023, 3205, 3025, 3082, 4174)
  and p.brandid != 7334
)
SELECT 
    t.customer_id,
    t.is_online,
    COALESCE(app.co_caidatapp, '0') AS co_caidatapp
FROM tmp2 t
LEFT JOIN "pinot"."default".rcm_khachhang_coappbhx app 
    ON CAST(t.customer_id AS VARCHAR) = app.customer_id;

  ;
  
  with
customer_orders AS (
    SELECT 
        a.crmcustomerid AS customer_id,
        CASE WHEN b.outputtypeid = 1903 THEN 1 ELSE 0 END AS is_online,
        DATE_TRUNC('month', FROM_UNIXTIME(a.outputdate / 1000 - 25200)) AS order_month
    FROM "pinot-group01"."default".bhx_inventory_inv_outputvoucher a
    JOIN "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b 
        ON a.outputvoucherid = b.outputvoucherid
    JOIN
        "pinot-group01"."default".bhx_bhx_masterdata_pm_product p 
        ON CAST(b.productid  AS VARCHAR) = CAST(p.productid AS VARCHAR)
    WHERE FROM_UNIXTIME(a.outputdate / 1000 - 25200) >= DATE('2025-06-11')
      AND FROM_UNIXTIME(a.outputdate / 1000 - 25200) <= DATE('2025-09-11')
      AND b.outputtypeid IN (3, 1903)
      AND a.crmcustomerid > 5
      and p.brandid  in (6621, 6449, 6561, 6611, 6883, 6442, 6736, 6568, 6895, 6556, 6612, 6448, 6549, 9665, 7047, 6840, 6792, 6571, 7973, 7050, 6819, 6972)
),
customers_with_orders_in_all_3_months as (
SELECT distinct customer_id,
is_online
FROM customer_orders
GROUP BY (customer_id, is_online)
HAVING COUNT(DISTINCT order_month) = 3
 )
SELECT 
    distinct
    c.customer_id,
    c.is_online,
    COALESCE(app.co_caidatapp, '0') AS co_caidatapp
FROM customers_with_orders_in_all_3_months c
LEFT JOIN "pinot"."default".rcm_khachhang_coappbhx app 
    ON CAST(c.customer_id AS VARCHAR) = app.customer_id
  
--   KH chưa từng mua sản phẩm Sensodyne (Mã brand: 6623) từ 01/2024 &&& có mua hàng tại BHX (on và offline) trong 30 ngày gần nhất (17/08-17/09)
--   tick app/ko app

CASE
		WHEN MAX(CASE WHEN b.outputtypeid = 1903 THEN 1 ELSE 0 END) = 1
            THEN 1
		ELSE 0
	END AS is_online;


with tmp1 as (
 SELECT 
    distinct a.crmcustomerid AS customer_id,
    CASE
		WHEN MAX(CASE WHEN b.outputtypeid = 1903 THEN 1 ELSE 0 END) = 1
            THEN 1
		ELSE 0
	END AS is_online
FROM "pinot-group01"."default".bhx_inventory_inv_outputvoucher a
JOIN "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b 
    ON a.outputvoucherid = b.outputvoucherid
JOIN
    "pinot-group01"."default".bhx_bhx_masterdata_pm_product p 
    ON CAST(b.productid  AS VARCHAR) = CAST(p.productid AS VARCHAR)
WHERE 
  FROM_UNIXTIME(a.outputdate / 1000 - 25200) >= DATE('2024-01-01')
  AND FROM_UNIXTIME(a.outputdate / 1000 - 25200) <= DATE('2025-09-17')
  AND b.outputtypeid IN (1903, 3)
  AND a.crmcustomerid > 5
  and p.brandid != 6623
GROUP BY a.crmcustomerid
),
tmp2 AS (
SELECT 
    distinct a.crmcustomerid AS customer_id,
    CASE
		WHEN MAX(CASE WHEN b.outputtypeid = 1903 THEN 1 ELSE 0 END) = 1
            THEN 1
		ELSE 0
	END AS is_online
FROM "pinot-group01"."default".bhx_inventory_inv_outputvoucher a
JOIN "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b 
    ON a.outputvoucherid = b.outputvoucherid
JOIN
    "pinot-group01"."default".bhx_bhx_masterdata_pm_product p 
    ON CAST(b.productid  AS VARCHAR) = CAST(p.productid AS VARCHAR)
WHERE 
  FROM_UNIXTIME(a.outputdate / 1000 - 25200) >= DATE('2025-08-17')
  AND FROM_UNIXTIME(a.outputdate / 1000 - 25200) <= DATE('2025-09-17')
  AND b.outputtypeid IN (1903, 3)
  AND a.crmcustomerid > 5
GROUP BY a.crmcustomerid 
),
tmp3 AS (
SELECT tmp2.customer_id,
tmp2.is_online
FROM tmp2
JOIN tmp1
ON tmp1.customer_id = tmp2.customer_id
)
SELECT 
    t.customer_id,
    t.is_online,
    COALESCE(app.co_caidatapp, '0') AS co_caidatapp
FROM tmp3 t
LEFT JOIN "pinot"."default".rcm_khachhang_coappbhx app 
    ON CAST(t.customer_id AS VARCHAR) = app.customer_id;

-- KH có mua hàng tại BHX (on và offline) từ 01/06/2025-31/08/2025, Trong đó:
-- + Với KH offline thì chỉ lấy KH có định danh 
-- + Mỗi tháng có phát sinh ít nhất 1 đơn hàng bất kỳ  và tổng chi tiêu  >1 triệu/tháng
-- + Trong giỏ hàng khách từng mua ít nhất 1 sản phẩm (chi tiết trong file)

WITH tmp1 AS (
SELECT 
    distinct a.crmcustomerid AS customer_id,
	DATE_TRUNC('month', FROM_UNIXTIME(a.outputdate / 1000 - 25200)) AS order_month
FROM "pinot-group01"."default".bhx_inventory_inv_outputvoucher a
JOIN "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b 
    ON a.outputvoucherid = b.outputvoucherid
JOIN
    "pinot-group01"."default".bhx_bhx_masterdata_pm_product p 
    ON CAST(b.productid  AS VARCHAR) = CAST(p.productid AS VARCHAR)
WHERE 
  FROM_UNIXTIME(a.outputdate / 1000 - 25200) >= DATE('2025-06-01')
  AND FROM_UNIXTIME(a.outputdate / 1000 - 25200) <= DATE('2025-08-31')
  AND b.outputtypeid IN (1903, 3)
  AND a.crmcustomerid > 5
),
tmp2 as (
SELECT distinct customer_id
FROM tmp1
GROUP BY (customer_id)
HAVING COUNT(DISTINCT order_month) = 3
),
tmp3 AS (
SELECT 
    distinct a.crmcustomerid AS customer_id,
    CASE
		WHEN MAX(CASE WHEN b.outputtypeid = 1903 THEN 1 ELSE 0 END) = 1
            THEN 1
		ELSE 0
	END AS is_online
--	Round(SUM(ROUND(b.saleprice * (1 + (CAST(b.vat AS DOUBLE) / 100)), 0) * b.quantity),0) AS revenue
FROM "pinot-group01"."default".bhx_inventory_inv_outputvoucher a
JOIN "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b 
    ON a.outputvoucherid = b.outputvoucherid
JOIN
    "pinot-group01"."default".bhx_bhx_masterdata_pm_product p 
    ON CAST(b.productid  AS VARCHAR) = CAST(p.productid AS VARCHAR)
WHERE 
--  FROM_UNIXTIME(a.outputdate / 1000 - 25200) >= DATE('2025-06-01')
--  AND FROM_UNIXTIME(a.outputdate / 1000 - 25200) <= DATE('2025-08-31')
