--    1. Những người mua dầu gội chưa mua dầu xả rejoice/ dầu xả pantene mà đã mua dầu gội/xả của những hãng khác trong 1 tháng gần nhất
    ;WITH 
tmp1 AS (
-- mua dầu gội P&G và mua gội xả hãng khác
SELECT
	DISTINCT a.crmcustomerid AS customer_id,
	CASE
		WHEN MAX(CASE WHEN b.outputtypeid = 1903 THEN 1 ELSE 0 END) = 1
            THEN 1
		ELSE 0
	END AS is_online
FROM
	"pinot-group01"."default".bhx_inventory_inv_outputvoucher a
JOIN "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b 
    ON
	a.outputvoucherid = b.outputvoucherid
JOIN
    "pinot-group01"."default".bhx_bhx_masterdata_pm_product p 
    ON
	CAST(b.productid AS VARCHAR) = CAST(p.productid AS VARCHAR)
WHERE
	FROM_UNIXTIME(a.outputdate / 1000 - 25200) >= DATE('2025-09-01')
	AND FROM_UNIXTIME(a.outputdate / 1000 - 25200) < DATE('2025-10-01')
	AND b.outputtypeid IN (1903, 3)
	AND a.crmcustomerid > 5
	AND p.subgroupid IN (3123, 3060, 2837)
	AND p.brandid IN (10410, 13864, 7485, 9709, 12265, 6150, 8260, 6549, 6560, 14626, 6571, 6568, 6921, 8228, 122, 6852, 13866, 6841, 13868, 10172, 8950, 10171, 11261, 6558, 9111, 9327, 11418, 6559, 6922, 6556, 6557, 10208, 6930, 8874, 6550, 11263, 11262, 8875, 6561, 6562, 11272, 6924, 12994, 6563, 6923, 11998, 11453, 6564, 6842, 15233, 6566, 11265, 9236, 1334, 6367, 11264, 6837, 7656, 14404, 7997, 14350, 6570, 13597, 10889, 14892, 13338, 8725, 13498, 20415, 9201, 7567, 7244, 9611, 13513, 10133, 11574, 20413, 13377, 8704, 12333, 13093, 11463, 18471, 13073, 13576, 19913, 8831, 9964, 18631, 14624, 14623, 10106, 14603, 14986, 20555, 14634, 13179, 13178, 13201, 15371, 8901, 9610, 13427, 10142, 12253, 8563, 8533, 9618, 8705, 8720, 8553, 8655, 8601, 8496, 9055, 8992, 14472, 14235, 9079, 14250, 17484, 15535, 8559, 11502, 9846, 9259, 15053, 8599, 11582, 8555, 9205, 9078, 8562, 13215, 8890, 15575, 13175, 13174, 9232, 13857, 12151, 13860, 14111, 15054, 7890, 10507)
GROUP BY
	a.crmcustomerid
),
tmp2 AS (
-- chưa mua dầu xả
SELECT
	a.crmcustomerid AS customer_id
FROM
	"pinot-group01"."default".bhx_inventory_inv_outputvoucher a
JOIN "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b
      ON
	a.outputvoucherid = b.outputvoucherid
JOIN "pinot-group01"."default".bhx_bhx_masterdata_pm_product p
      ON
	CAST(b.productid AS VARCHAR) = CAST(p.productid AS VARCHAR)
WHERE
	b.outputtypeid IN (1903, 3)
		AND FROM_UNIXTIME(a.outputdate / 1000 - 25200) >= DATE('2025-09-01')
			AND FROM_UNIXTIME(a.outputdate / 1000 - 25200) < DATE('2025-10-01')
				AND a.crmcustomerid > 5
			GROUP BY
				a.crmcustomerid
			HAVING
				MAX(CASE WHEN (p.subgroupid = 2837 
				AND p.brandid IN (6567, 6565, 10131))THEN 1 ELSE 0 END) = 0
),
tmp3 AS (
SELECT
	tmp1.*
FROM
	tmp1
LEFT JOIN tmp2 ON
	tmp1.customer_id = tmp2.customer_id 
)
SELECT
	t.customer_id,
	t.is_online,
	COALESCE(app.co_caidatapp, '0') AS co_caidatapp
FROM
	tmp3 t
LEFT JOIN "pinot"."default".rcm_khachhang_coappbhx app 
ON
CAST(t.customer_id AS VARCHAR) = app.customer_id
    ;


--2. Những khách hàng mua food mà chưa mua dầu gội/ dầu xả của P&G

WITH 
tmp1 as ( -- mua food 993, 1235, 1236, 1234, 1254
 SELECT 
    distinct a.crmcustomerid AS customer_id,
 CASE
	WHEN MAX(CASE WHEN b.outputtypeid = 1903 THEN 1 ELSE 0 END) = 1
            THEN 1
	ELSE 0
END AS is_online
FROM "pinot-group01"."default".bhx_inventory_inv_outputvoucher a
JOIN "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b 
    ON a.outputvoucherid = b.outputvoucherid
JOIN
    "pinot-group01"."default".bhx_bhx_masterdata_pm_product p 
    ON CAST(b.productid  AS VARCHAR) = CAST(p.productid AS VARCHAR)
WHERE 
  FROM_UNIXTIME(a.outputdate / 1000 - 25200) >= DATE('2025-09-01')
  AND FROM_UNIXTIME(a.outputdate / 1000 - 25200) < DATE('2025-10-01')
  AND b.outputtypeid IN (1903, 3)
  AND a.crmcustomerid > 5
  and p.maingroupid   IN (993, 1235, 1236, 1234, 1254)
 GROUP BY a.crmcustomerid
),
tmp2 AS ( -- chưa mua dầu gội/ dầu xả của P&G
SELECT a.crmcustomerid AS customer_id
FROM
"pinot-group01"."default".bhx_inventory_inv_outputvoucher a
JOIN "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b
      ON
a.outputvoucherid = b.outputvoucherid
JOIN "pinot-group01"."default".bhx_bhx_masterdata_pm_product p
      ON
CAST(b.productid AS VARCHAR) = CAST(p.productid AS VARCHAR)
WHERE
b.outputtypeid IN (1903, 3)
AND FROM_UNIXTIME(a.outputdate / 1000 - 25200) >= DATE('2025-09-01')
AND FROM_UNIXTIME(a.outputdate / 1000 - 25200) < DATE('2025-10-01')
AND a.crmcustomerid > 5
GROUP BY
a.crmcustomerid
HAVING MAX(CASE WHEN (p.subgroupid IN (3123, 2837, 3060)
                  AND p.brandid   IN (6567, 6560, 6565, 10133, 10131, 10106)) THEN 1 ELSE 0 END) = 0
),
tmp3 AS (
SELECT tmp1.* FROM tmp1
LEFT JOIN tmp2 ON tmp1.customer_id = tmp2.customer_id 
)
SELECT 
    t.customer_id,
    t.is_online,
    COALESCE(app.co_caidatapp, '0') AS co_caidatapp
FROM tmp3 t
LEFT JOIN "pinot"."default".rcm_khachhang_coappbhx app 
    ON CAST(t.customer_id AS VARCHAR) = app.customer_id
    
    ;
    
