    COALESCE(app.co_caidatapp, '0') AS co_caidatapp
FROM tmp3 t
LEFT JOIN "pinot"."default".rcm_khachhang_coappbhx app 
    ON CAST(t.customer_id AS VARCHAR) = app.customer_id
    
    
--    tập KH Online từ 01/09-30/09
--    Tập 2: Có mua hàng của hãng GẤU ĐỎ (6512) thuộc  nhóm Mì ăn liền ( 3052)
WITH tmp3 AS (
 SELECT 
    a.crmcustomerid AS customer_id
FROM "pinot-group01"."default".bhx_inventory_inv_outputvoucher a
JOIN "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b 
    ON a.outputvoucherid = b.outputvoucherid
JOIN
    "pinot-group01"."default".bhx_bhx_masterdata_pm_product p 
    ON CAST(b.productid  AS VARCHAR) = CAST(p.productid AS VARCHAR)
WHERE 
  FROM_UNIXTIME(a.outputdate / 1000 - 25200) >= DATE('2025-09-01')
  AND FROM_UNIXTIME(a.outputdate / 1000 - 25200) < DATE('2025-10-01')
  AND b.outputtypeid IN (1903)
  AND a.crmcustomerid > 5
  AND p.subgroupid IN (3052)
  and p.brandid IN (6512)
)
SELECT 
    t.customer_id,
    COALESCE(app.co_caidatapp, '0') AS co_caidatapp
FROM tmp3 t
LEFT JOIN "pinot"."default".rcm_khachhang_coappbhx app 
    ON CAST(t.customer_id AS VARCHAR) = app.customer_id
    
    
--    tập KH Online từ 01/09-30/09
--    Tập 3: Có mua hàng của nhóm nước dinh dưỡng (3024)

WITH tmp3 AS (
 SELECT 
    a.crmcustomerid AS customer_id
FROM "pinot-group01"."default".bhx_inventory_inv_outputvoucher a
JOIN "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b 
    ON a.outputvoucherid = b.outputvoucherid
JOIN
    "pinot-group01"."default".bhx_bhx_masterdata_pm_product p 
    ON CAST(b.productid  AS VARCHAR) = CAST(p.productid AS VARCHAR)
WHERE 
  FROM_UNIXTIME(a.outputdate / 1000 - 25200) >= DATE('2025-09-01')
  AND FROM_UNIXTIME(a.outputdate / 1000 - 25200) < DATE('2025-10-01')
  AND b.outputtypeid IN (1903)
  AND a.crmcustomerid > 5
  AND p.subgroupid IN (3024)
)
SELECT 
    t.customer_id,
    COALESCE(app.co_caidatapp, '0') AS co_caidatapp
FROM tmp3 t
LEFT JOIN "pinot"."default".rcm_khachhang_coappbhx app 
    ON CAST(t.customer_id AS VARCHAR) = app.customer_id;


--    Kh có mua hàng online tháng 8, 9, 10 mà chưa mua BVS từ 1/2024 (đk chưa mua mở ra cả onl+ off ) và đánh dấu có app
	


WITH mua_online_3month AS (
 SELECT 
    DISTINCT a.crmcustomerid AS customer_id
FROM "pinot-group01"."default".bhx_inventory_inv_outputvoucher a
JOIN "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b 
    ON a.outputvoucherid = b.outputvoucherid
WHERE 
  FROM_UNIXTIME(a.outputdate / 1000 - 25200) >= DATE('2025-08-01')
  AND FROM_UNIXTIME(a.outputdate / 1000 - 25200) < DATE('2025-11-01')
  AND b.outputtypeid IN (1903)
  AND a.crmcustomerid > 5
),
chuamua_bvs AS (
SELECT 
    a.crmcustomerid AS customer_id
FROM "pinot-group01"."default".bhx_inventory_inv_outputvoucher a
JOIN "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b 
    ON a.outputvoucherid = b.outputvoucherid
JOIN
    "pinot-group01"."default".bhx_bhx_masterdata_pm_product p 
    ON CAST(b.productid  AS VARCHAR) = CAST(p.productid AS VARCHAR)
WHERE 
  FROM_UNIXTIME(a.outputdate / 1000 - 25200) >= DATE('2024-01-01')
  AND b.outputtypeid IN (1903, 3)
  AND a.crmcustomerid > 5
GROUP BY
a.crmcustomerid
HAVING SUM(CASE WHEN p.subgroupid IN (2551) THEN 1 ELSE 0 END) = 0
),
tmp AS (
SELECT  mo3.customer_id 
FROM mua_online_3month mo3
JOIN chuamua_bvs cb
ON mo3.customer_id = cb.customer_id
)
SELECT 
    t.customer_id,
    COALESCE(app.co_caidatapp, '0') AS co_caidatapp
FROM tmp t
LEFT JOIN "pinot"."default".rcm_khachhang_coappbhx app 
    ON CAST(t.customer_id AS VARCHAR) = app.customer_id;    
    
;
WITH tmp1 AS (
SELECT 
    distinct a.crmcustomerid AS customer_id,
 CASE
	WHEN MAX(CASE WHEN b.outputtypeid = 1903 THEN 1 ELSE 0 END) = 1
            THEN 1
	ELSE 0
END AS is_online
FROM "pinot-group01"."default".bhx_inventory_inv_outputvoucher a
JOIN "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b 
    ON a.outputvoucherid = b.outputvoucherid
JOIN
    "pinot-group01"."default".bhx_bhx_masterdata_pm_product p 
    ON CAST(b.productid  AS VARCHAR) = CAST(p.productid AS VARCHAR)
WHERE 
  FROM_UNIXTIME(a.outputdate / 1000 - 25200) >= DATE('2025-10-01')
  AND FROM_UNIXTIME(a.outputdate / 1000 - 25200) < DATE('2026-01-01')
  AND b.outputtypeid IN (1903, 3)
  AND a.crmcustomerid > 5
  AND p.subgroupid IN (3141)
 GROUP BY a.crmcustomerid
 ),
tmp2 AS (
SELECT 
    distinct a.crmcustomerid AS customer_id
FROM "pinot-group01"."default".bhx_inventory_inv_outputvoucher a
JOIN "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b 
    ON a.outputvoucherid = b.outputvoucherid
JOIN
    "pinot-group01"."default".bhx_bhx_masterdata_pm_product p 
    ON CAST(b.productid  AS VARCHAR) = CAST(p.productid AS VARCHAR)
WHERE 
  FROM_UNIXTIME(a.outputdate / 1000 - 25200) >= DATE('2024-01-01')
  AND FROM_UNIXTIME(a.outputdate / 1000 - 25200) < DATE('2026-01-01')
  AND b.outputtypeid IN (1903, 3)
  AND a.crmcustomerid > 5
--  AND p.subgroupid IN (3140)
 GROUP BY a.crmcustomerid
HAVING SUM(CASE WHEN p.productid IN ('9892845000224', '9892845000331', '1053140000181', '1053140000180') THEN 1 ELSE 0 END) = 0
)
SELECT 
tmp1.customer_id ,
tmp1.is_online
FROM tmp1
JOIN tmp2 ON tmp1.customer_id = tmp2.customer_id;

    
WITH buy AS (
SELECT 
    a.crmcustomerid AS customer_id,
 CASE
	WHEN MAX(CASE WHEN b.outputtypeid = 1903 THEN 1 ELSE 0 END) = 1
            THEN 1
	ELSE 0
END AS is_online
FROM "pinot-group01"."default".bhx_inventory_inv_outputvoucher a
JOIN "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b 
    ON a.outputvoucherid = b.outputvoucherid
JOIN
    "pinot-group01"."default".bhx_bhx_masterdata_pm_product p 
    ON CAST(b.productid  AS VARCHAR) = CAST(p.productid AS VARCHAR)
WHERE 
  FROM_UNIXTIME(a.outputdate / 1000 - 25200) >= DATE('2024-01-01')
  AND FROM_UNIXTIME(a.outputdate / 1000 - 25200) < DATE('2025-12-19')
  AND b.outputtypeid IN (1903, 3)
  AND a.crmcustomerid > 5
--  AND p.maingroupid  IN (1056)
 GROUP BY a.crmcustomerid
 ),
not_buy AS (
SELECT 
    distinct a.crmcustomerid AS customer_id
FROM "pinot-group01"."default".bhx_inventory_inv_outputvoucher a
JOIN "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b 
    ON a.outputvoucherid = b.outputvoucherid
JOIN
    "pinot-group01"."default".bhx_bhx_masterdata_pm_product p 
    ON CAST(b.productid  AS VARCHAR) = CAST(p.productid AS VARCHAR)
WHERE 
  FROM_UNIXTIME(a.outputdate / 1000 - 25200) >= DATE('2025-12-19')
  AND FROM_UNIXTIME(a.outputdate / 1000 - 25200) < DATE('2026-01-22')
  AND b.outputtypeid IN (1903, 3)
  AND a.crmcustomerid > 5
--  AND p.maingroupid  IN (1056)
 GROUP BY a.crmcustomerid
HAVING SUM(CASE WHEN p.maingroupid  IN (3054) THEN 1 ELSE 0 END) = 0
)
SELECT 
buy.customer_id ,
buy.is_online
FROM buy
JOIN not_buy ON not_buy.customer_id = buy.customer_id
    ;

SELECT
            a.crmcustomerid,
            a.outputvoucherid AS invoutputvoucherid,
            a.outputdate AS outputdate_timestamp,
            b.outputtypeid,
            b.productid,
            pm.productname,
            b.quantity,
            b.vat,
            round(b.saleprice*(1 + (CAST(b.vat AS DOUBLE) / 100 )),0) as saleprice,
            round(b.retailprice*(1 + (CAST(b.vat AS DOUBLE) / 100 )),0) as retailprice,
            a.totalamountbf AS totalbf,
            a.storeid,
            pm.subgroupid,
            pm.maingroupid
        FROM
            "pinot-group01"."default".bhx_inventory_inv_outputvoucher a
        JOIN
            "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b
            ON a.outputvoucherid = b.outputvoucherid
        JOIN
            "pinot-group01"."default".bhx_bhx_masterdata_pm_product pm
            ON b.productid = pm.productid
        JOIN 
            "pinot-group01"."default".bhx_bhx_masterdata_pm_outputtype outputtype
            ON b.outputtypeid = outputtype.outputtypeid
        WHERE
            a.outputdate >= 1740960000000
            AND a.outputdate <= 1741046399999
